-- 9043_s4_statement_drafts.sql -- AI-first statement intake (G1, G4, G7 of docs/s4/S4_AI_First_Workflows_Design_2026-11-16.md;
-- Owner decisions OD-AI-1..OD-AI-4, B1-B4, Q1, OD-APR-1 of 2026-11-16/17).
-- The AI reads a statement and submits it whole; the database checks it; a member approves it in the PWA (C-04). No parser.
--   NEW bnx.statement_gap_note (append-only): a member's explanation of a gap or a balance break between two statements of
--       one account-currency (no activity, statement missing, account opened or closed, other).
--   NEW bnx.statement_fingerprint: the source fingerprint of a statement line, computed here (never by the AI) from the
--       account-currency, date, ledger-sign amount, normalized description or bank reference, and the occurrence number.
--   NEW bnx.statement_continuity: how a statement plan meets the nearest earlier live statement plan of its account-currency
--       (first / ok / gap / break / explained).
--   NEW bnx.cmd_draft_statement (tier 1; RC-DRAFT; MCP fin.draft.create_statement, scope finance.draft): one statement with
--       its printed opening and closing balances and every line. Owed-positive statements (cards, loans) are turned to the
--       ledger sign. The lines become the items of one plan (kind ai_draft from an AI host, import from the PWA, which needs
--       can_post), with the statement in its scope and fingerprints required; the existing checks V-01..V-10 run, V-04 being
--       the balance chain opening + lines = closing.
--   NEW bnx.q_statement_chain (tier 0; MCP fin.statements.chain, scope finance.read): the statements of one account-currency
--       in period order with balances, state, holds and continuity, and the recorded gap explanations.
--   NEW bnx.cmd_explain_statement_gap (tier 2; PWA only): record an explanation; the plans of that account-currency are
--       revalidated by their next validation.
--   MODIFY bnx.intake_validate (9010): V-11 statement continuity. A balance break holds the plan (BALANCE_BREAK) unless
--       explained; a calendar gap with matching balances is reported as a finding. V-12: an item before the opening anchor
--       of an account it touches holds the plan (BEFORE_OPENING) instead of failing after approval in the posting worker.
--       Every changed line is marked "-- 9043".
--   function_scope: q_ledger_accounts becomes an MCP read tool (fin.ledger.accounts, finance.read), so the AI can find the
--       categories it proposes; the two new tools as above.
-- Expand-only. Catalog: the delta block below (generated by tools/s4/catalog_build.py).
set role bnx_definer;

-- ---------- NEW bnx.statement_gap_note ----------
create table bnx.statement_gap_note(
  id uuid primary key, account_currency_id uuid not null references bnx.account_currency,
  gap_from date not null, gap_to date not null check (gap_to >= gap_from),
  reason text not null check (reason in ('no_activity','statement_missing','account_opened','account_closed','other')),
  note text check (length(note) <= 500), member_id uuid not null references bnx.member, recorded_at timestamptz not null default now());
create trigger t_append_only before update or delete on bnx.statement_gap_note for each row execute function bnx.trg_append_only();

-- ---------- NEW bnx.statement_fingerprint ----------
create function bnx.statement_fingerprint(p_acid uuid, p_date date, p_amount numeric, p_desc text, p_ref text, p_occ int) returns text
language sql immutable set search_path = pg_catalog, pg_temp as $$
  select encode(sha256(convert_to(p_acid::text || '|' || p_date::text || '|' || trim_scale(p_amount)::text || '|'
         || coalesce(nullif(btrim(p_ref), ''), lower(regexp_replace(btrim(coalesce(p_desc, '')), '\s+', ' ', 'g'))) || '|' || p_occ::text, 'UTF8')), 'hex')
$$;

-- ---------- NEW bnx.statement_continuity ----------
create function bnx.statement_continuity(p_plan uuid) returns jsonb
language plpgsql stable security definer set search_path = pg_catalog, pg_temp as $$
declare pl record; st jsonb; acid uuid; pf date; prev record; explained boolean; gfrom date; gto date;
begin
  select * into pl from bnx.posting_plan where id = p_plan;
  st := pl.scope->'statement';
  if st is null then return jsonb_build_object('status', 'n/a'); end if;
  acid := (pl.scope->>'account_currency_id')::uuid; pf := (st->>'period_from')::date;
  select o.id, (o.scope->'statement'->>'period_to')::date pt, (o.scope->'statement'->>'closing')::numeric cl into prev
    from bnx.posting_plan o
   where o.id <> p_plan and o.scope ? 'statement' and (o.scope->>'account_currency_id')::uuid = acid
     and o.state in ('frozen','approved','executing','sealed','activated')
     and (o.scope->'statement'->>'period_to')::date <= pf
   order by (o.scope->'statement'->>'period_to')::date desc, o.created_at desc limit 1;
  if prev.id is null then return jsonb_build_object('status', 'first'); end if;
  gfrom := prev.pt + 1; gto := pf - 1;
  select exists (select 1 from bnx.statement_gap_note g where g.account_currency_id = acid
                  and g.gap_from <= greatest(pf, prev.pt) and g.gap_to >= least(pf, prev.pt)) into explained;
  return jsonb_build_object('status', case when prev.cl <> (st->>'opening')::numeric then case when explained then 'explained' else 'break' end
                                           when gto >= gfrom then case when explained then 'explained' else 'gap' end
                                           else 'ok' end,
                            'previous_plan_id', prev.id, 'previous_period_to', prev.pt, 'previous_closing', trim_scale(prev.cl)::text,
                            'opening', trim_scale((st->>'opening')::numeric)::text,
                            'gap_from', case when gto >= gfrom then gfrom end, 'gap_to', case when gto >= gfrom then gto end);
end $$;

-- ---------- NEW bnx.cmd_draft_statement ----------
create function bnx.cmd_draft_statement(cred jsonb, cmd jsonb) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare a bnx.actor := bnx.resolve_actor(cred); rc jsonb; r jsonb; acid uuid; ac record; pf date; pt date; sg int; sc text;
        op numeric; cl numeric; ln jsonb; it jsonb; items jsonb := '[]'; d date; amt numeric; occ int; fp text; k text; seen jsonb := '{}';
        kind text; key text; desc_ text; ref text; old uuid; opl record;
begin
  perform bnx.require(a, 1);
  rc := bnx.idem_begin(a, 'draft_statement', cmd); if rc is not null then return rc; end if;
  begin
    acid := (cmd->>'account_currency_id')::uuid; pf := (cmd->>'period_from')::date; pt := (cmd->>'period_to')::date;
    op := (cmd->>'opening_balance')::numeric; cl := (cmd->>'closing_balance')::numeric;
  exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
    perform bnx.fail('VALIDATION_FAILED', 'P0422', 'account_currency_id, period, balances');
  end;
  if acid is null or pf is null or pt is null or pf > pt or op is null or cl is null then
    perform bnx.fail('VALIDATION_FAILED', 'P0422', 'account_currency_id, period_from <= period_to, opening_balance, closing_balance'); end if;
  sc := coalesce(cmd->>'sign_convention', '');
  if sc not in ('asset_positive','owed_positive') then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'sign_convention'); end if;
  sg := case when sc = 'owed_positive' then -1 else 1 end;
  if jsonb_typeof(cmd->'lines') is distinct from 'array' or jsonb_array_length(cmd->'lines') = 0 or jsonb_array_length(cmd->'lines') > 1000 then
    perform bnx.fail('VALIDATION_FAILED', 'P0422', 'lines: 1 to 1000'); end if;
  if cmd ? 'account_last4' and coalesce(cmd->>'account_last4', '') !~ '^[0-9]{4}$' then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'account_last4'); end if;
  if cmd ? 'source_file_id' and coalesce(cmd->>'source_file_id', '') !~ '^[A-Za-z0-9_-]{10,128}$' then
    perform bnx.fail('VALIDATION_FAILED', 'P0422', 'source_file_id'); end if;
  if length(coalesce(cmd->>'institution', '')) > 80 then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'institution'); end if;
  if not (acid in (select bnx.actor_visible_acs(a))) then perform bnx.fail('NOT_AVAILABLE', 'P0404'); end if;
  select * into ac from bnx.account_currency where id = acid;
  perform bnx.assert_scale(op, ac.currency, 'opening_balance'); perform bnx.assert_scale(cl, ac.currency, 'closing_balance');
  kind := case when a.channel = 'mcp' then 'ai_draft' else 'import' end;
  -- a corrected statement replaces the caller's own open statement draft of the same account-currency (its lines would
  -- otherwise count as duplicates of the live plan)
  if cmd ? 'supersedes_plan_id' then
    begin old := (cmd->>'supersedes_plan_id')::uuid;
    exception when invalid_text_representation then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'supersedes_plan_id'); end;
    select * into opl from bnx.posting_plan where id = old for update;
    if not found or not opl.scope ? 'statement' or (opl.scope->>'account_currency_id')::uuid <> acid then
      perform bnx.fail('NOT_AVAILABLE', 'P0404'); end if;
    if opl.kind = 'import' then                                     -- a member's own statement import (PWA)
      if a.channel = 'mcp' or opl.created_by is distinct from a.member_id then perform bnx.fail('NOT_AVAILABLE', 'P0404'); end if;
    else perform bnx.draft_owned(a, old); end if;
    if opl.state <> 'frozen' then perform bnx.fail('PLAN_NOT_REVISABLE', 'P0409', opl.state); end if;
  end if;
  if kind = 'import' and not bnx.actor_can_post(a, acid) then perform bnx.fail('NOT_POSTABLE', 'P0403'); end if;
  for ln in select * from jsonb_array_elements(cmd->'lines') loop
    if jsonb_typeof(ln) <> 'object' then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'line'); end if;
    for k in select jsonb_object_keys(ln) loop
      if not k = any(array['date','amount','description','bank_ref','counter_ledger_account_id','economic_type','lines','needs_review']) then
        perform bnx.fail('VALIDATION_FAILED', 'P0422', 'line field ' || k); end if;
    end loop;
    begin
      d := (ln->>'date')::date; amt := (ln->>'amount')::numeric;
    exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
      perform bnx.fail('VALIDATION_FAILED', 'P0422', 'line date and amount');
    end;
    if d is null or amt is null then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'line date and amount'); end if;
    desc_ := btrim(coalesce(ln->>'description', '')); ref := btrim(coalesce(ln->>'bank_ref', ''));
    if desc_ = '' or length(desc_) > 200 or length(ref) > 64 then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'line description / bank_ref'); end if;
    amt := amt * sg;
    key := d::text || '|' || trim_scale(amt)::text || '|' || coalesce(nullif(ref, ''), lower(regexp_replace(desc_, '\s+', ' ', 'g')));
    occ := coalesce((seen->>key)::int, 0) + 1; seen := seen || jsonb_build_object(key, occ);
    fp := bnx.statement_fingerprint(acid, d, amt, desc_, ref, occ);
    it := jsonb_strip_nulls(jsonb_build_object('transaction_date', d, 'description', desc_, 'amount', trim_scale(amt)::text,
            'source_fingerprint', fp, 'counter_ledger_account_id', ln->>'counter_ledger_account_id', 'economic_type', ln->>'economic_type',
            'lines', ln->'lines', 'needs_review', ln->'needs_review'));
    items := items || jsonb_build_array(it);
  end loop;
  if old is not null then perform bnx.plan_terminate(old, 'superseded', 'revised by a corrected statement'); end if;
  r := bnx.plan_create(a, kind, jsonb_build_object('account_currency_id', acid, 'date_from', pf, 'date_to', pt, 'items', items,
         'evidence_file_ids', '[]'::jsonb, 'supersedes_plan_id', cmd->>'supersedes_plan_id', 'require_fingerprints', true,
         'statement', jsonb_strip_nulls(jsonb_build_object('period_from', pf, 'period_to', pt,
             'opening', trim_scale(op * sg)::text, 'closing', trim_scale(cl * sg)::text, 'sign_convention', sc,
             'printed_opening', trim_scale(op)::text, 'printed_closing', trim_scale(cl)::text, 'line_count', jsonb_array_length(items),
             'institution', nullif(btrim(cmd->>'institution'), ''), 'account_last4', cmd->>'account_last4',
             'source_file_id', cmd->>'source_file_id'))));
  r := r || jsonb_build_object('continuity', bnx.statement_continuity((r->>'plan_id')::uuid));
  perform bnx.audit(a, 'draft_statement', jsonb_build_object('plan_id', r->>'plan_id', 'kind', r->>'kind', 'lines', jsonb_array_length(items)), cmd, null);
  return bnx.idem_end(a, 'draft_statement', cmd, r);
end $$;

-- ---------- NEW bnx.q_statement_chain ----------
create function bnx.q_statement_chain(cred jsonb, q jsonb) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare a bnx.actor := bnx.resolve_actor(cred); acid uuid; sts jsonb; notes jsonb;
begin
  perform bnx.require(a, 0);
  begin acid := (q->>'account_currency_id')::uuid;
  exception when invalid_text_representation then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'account_currency_id'); end;
  if acid is null then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'account_currency_id'); end if;
  if not (acid in (select bnx.actor_visible_acs(a))) then perform bnx.fail('NOT_AVAILABLE', 'P0404'); end if;
  select coalesce(jsonb_agg(jsonb_build_object('plan_id', p.id, 'kind', p.kind, 'state', p.state,
           'period_from', p.scope->'statement'->>'period_from', 'period_to', p.scope->'statement'->>'period_to',
           'opening', p.scope->'statement'->>'opening', 'closing', p.scope->'statement'->>'closing',
           'printed_opening', p.scope->'statement'->>'printed_opening', 'printed_closing', p.scope->'statement'->>'printed_closing',
           'sign_convention', p.scope->'statement'->>'sign_convention', 'line_count', p.item_count,
           'hold_reasons', to_jsonb(p.hold_reasons), 'continuity', bnx.statement_continuity(p.id))
           order by (p.scope->'statement'->>'period_from')::date, p.created_at), '[]')
    into sts from bnx.posting_plan p
   where p.scope ? 'statement' and (p.scope->>'account_currency_id')::uuid = acid and p.state not in ('void','superseded');
  select coalesce(jsonb_agg(jsonb_build_object('gap_from', g.gap_from, 'gap_to', g.gap_to, 'reason', g.reason, 'note', g.note,
           'recorded_at', g.recorded_at) order by g.gap_from, g.recorded_at), '[]')
    into notes from bnx.statement_gap_note g where g.account_currency_id = acid;
  return jsonb_build_object('account_currency_id', acid, 'statements', sts, 'gap_notes', notes);
end $$;

-- ---------- NEW bnx.cmd_explain_statement_gap ----------
create function bnx.cmd_explain_statement_gap(cred jsonb, cmd jsonb) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare a bnx.actor := bnx.resolve_actor(cred); rc jsonb; acid uuid; gf date; gt date; n uuid := gen_random_uuid();
begin
  perform bnx.require(a, 2);
  rc := bnx.idem_begin(a, 'explain_statement_gap', cmd); if rc is not null then return rc; end if;
  begin
    acid := (cmd->>'account_currency_id')::uuid; gf := (cmd->>'gap_from')::date; gt := (cmd->>'gap_to')::date;
  exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
    perform bnx.fail('VALIDATION_FAILED', 'P0422', 'account_currency_id, gap_from, gap_to');
  end;
  if acid is null or gf is null or gt is null or gt < gf then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'account_currency_id, gap_from <= gap_to'); end if;
  if coalesce(cmd->>'reason', '') not in ('no_activity','statement_missing','account_opened','account_closed','other') then
    perform bnx.fail('VALIDATION_FAILED', 'P0422', 'reason'); end if;
  if length(coalesce(cmd->>'note', '')) > 500 then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'note'); end if;
  if not bnx.actor_can_post(a, acid) then perform bnx.fail('NOT_POSTABLE', 'P0403'); end if;
  insert into bnx.statement_gap_note values (n, acid, gf, gt, cmd->>'reason', nullif(btrim(cmd->>'note'), ''), a.member_id, now());
  perform bnx.audit(a, 'explain_statement_gap', jsonb_build_object('gap_note_id', n, 'account_currency_id', acid), cmd, null);
  return bnx.idem_end(a, 'explain_statement_gap', cmd, jsonb_build_object('gap_note_id', n));
end $$;

-- ---------- MODIFY bnx.intake_validate (9010): V-11 ----------
create or replace function bnx.intake_validate(p_plan uuid) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare pl record; acid uuid; acc record; ac record; it record; r jsonb := '{}'; holds text[] := '{}'; et text; why text; lines jsonb;
        vnow bigint; st jsonb; n int; x text; cont jsonb;   -- 9043 cont
begin
  select * into pl from bnx.posting_plan where id = p_plan for update;
  if not found then perform bnx.fail('NOT_FOUND', 'P0404'); end if;
  acid := (pl.scope->>'account_currency_id')::uuid;
  select * into ac from bnx.account_currency where id = acid;
  select * into acc from bnx.account where id = ac.account_id;
  select version into vnow from bnx.ledger_state;
  -- V-01 identity: account active; institution eligible (grandfathered accounts keep posting) or no institution (cash)
  if acc.id is null or acc.state <> 'active' or (acc.institution_id is not null and not bnx.institution_eligible(acc.institution_id)
                                                 and not acc.institution_grandfathered) then
    r := r || '{"V-01":"HOLD:IDENTITY"}'; holds := array_append(holds, 'IDENTITY');
  else r := r || '{"V-01":"ok"}'; end if;
  -- V-02 currency agreement of every line with its ledger account and of R1 items with the plan's account
  if exists (select 1 from bnx.posting_plan_item i cross join lateral jsonb_array_elements(bnx.plan_item_lines(p_plan, i.payload)) l
              join bnx.ledger_account la on la.id = (l->>'ledger_account_id')::uuid
             where i.plan_id = p_plan and la.currency <> l->>'currency')
     or exists (select 1 from bnx.posting_plan_item i where i.plan_id = p_plan and i.payload ? 'currency' and i.payload->>'currency' <> ac.currency) then
    r := r || '{"V-02":"HOLD:CURRENCY"}'; holds := array_append(holds, 'CURRENCY');
  else r := r || '{"V-02":"ok"}'; end if;
  -- V-03 duplicates: source fingerprint repeated in the plan, already imported (source_txn) or in another live plan;
  --      evidence sha256 repeated in the plan
  if exists (select 1 from bnx.posting_plan_item i where i.plan_id = p_plan and i.payload ? 'source_fingerprint'
              group by i.payload->>'source_fingerprint' having count(*) > 1)
     or exists (select 1 from bnx.posting_plan_item i join bnx.source_txn s on s.account_currency_id = acid
                  and encode(s.source_fingerprint, 'hex') = i.payload->>'source_fingerprint' where i.plan_id = p_plan)
     or exists (select 1 from bnx.posting_plan_item i join bnx.posting_plan_item o on o.payload->>'source_fingerprint' = i.payload->>'source_fingerprint'
                  join bnx.posting_plan op on op.id = o.plan_id and op.id <> p_plan
                   and op.state not in ('void','superseded','stale','suspended') and (op.scope->>'account_currency_id')::uuid = acid
                 where i.plan_id = p_plan and i.payload ? 'source_fingerprint')
     or exists (select 1 from bnx.posting_plan_item i where i.plan_id = p_plan and i.payload ? 'evidence_sha256'
                 group by i.payload->>'evidence_sha256' having count(*) > 1) then
    r := r || '{"V-03":"HOLD:DUPLICATE"}'; holds := array_append(holds, 'DUPLICATE');
  else r := r || '{"V-03":"ok"}'; end if;
  -- V-04 statement balance chain: opening + rows = closing
  st := pl.scope->'statement';
  if st is not null then
    if (st->>'opening')::numeric + coalesce((select sum((i.payload->>'amount')::numeric) from bnx.posting_plan_item i where i.plan_id = p_plan), 0)
       <> (st->>'closing')::numeric then
      r := r || '{"V-04":"HOLD:BALANCE_CHAIN"}'; holds := array_append(holds, 'BALANCE_CHAIN');
    else r := r || '{"V-04":"ok"}'; end if;
  else r := r || '{"V-04":"n/a"}'; end if;
  -- V-05 coverage: a statement period overlapping an already approved/activated statement plan of the same account-currency
  if st is not null and exists (select 1 from bnx.posting_plan o where o.id <> p_plan and o.scope ? 'statement'
        and (o.scope->>'account_currency_id')::uuid = acid and o.state in ('approved','executing','sealed','activated')
        and daterange((o.scope->'statement'->>'period_from')::date, (o.scope->'statement'->>'period_to')::date, '[]')
            && daterange((st->>'period_from')::date, (st->>'period_to')::date, '[]')) then
    r := r || '{"V-05":"HOLD:COVERAGE"}'; holds := array_append(holds, 'COVERAGE');
  else r := r || jsonb_build_object('V-05', case when st is null then 'n/a' else 'ok' end); end if;
  -- V-06 fingerprints present for every row of an import
  if pl.kind = 'import' and exists (select 1 from bnx.posting_plan_item i where i.plan_id = p_plan
                                     and coalesce(i.payload->>'source_fingerprint', '') = '') and coalesce((pl.scope->>'require_fingerprints')::boolean, false) then
    r := r || '{"V-06":"HOLD:FINGERPRINT"}'; holds := array_append(holds, 'FINGERPRINT');
  else r := r || jsonb_build_object('V-06', case when coalesce((pl.scope->>'require_fingerprints')::boolean, false) then 'ok' else 'n/a' end); end if;
  -- V-07 economic-type rule pre-check (B6.1, 9008) on every item
  n := 0;
  for it in select * from bnx.posting_plan_item where plan_id = p_plan order by seq loop
    et := bnx.plan_item_economic_type(it.payload);
    why := case when et is null then 'untyped' else bnx.economic_type_violation_lines(et, bnx.plan_item_lines(p_plan, it.payload)) end;
    if why is not null then n := n + 1; x := coalesce(x, 'seq ' || it.seq || ': ' || why); end if;
  end loop;
  if n > 0 then r := r || jsonb_build_object('V-07', 'HOLD:ECONOMIC_TYPE (' || x || ')'); holds := array_append(holds, 'ECONOMIC_TYPE');
  else r := r || '{"V-07":"ok"}'; end if;
  -- V-08 transfer pairs: both legs present (typed lines on two account-currencies) or the counter leg is a clearing account
  if exists (select 1 from bnx.posting_plan_item i where i.plan_id = p_plan
              and bnx.plan_item_economic_type(i.payload) in ('internal_transfer','card_repayment')
              and not exists (select 1 from jsonb_array_elements(bnx.plan_item_lines(p_plan, i.payload)) l
                                join bnx.ledger_account la on la.id = (l->>'ledger_account_id')::uuid where la.kind = 'clearing')
              and (select count(distinct ac2.id) from jsonb_array_elements(bnx.plan_item_lines(p_plan, i.payload)) l
                     join bnx.account_currency ac2 on ac2.ledger_account_id = (l->>'ledger_account_id')::uuid) < 2) then
    r := r || '{"V-08":"HOLD:TRANSFER_PAIR"}'; holds := array_append(holds, 'TRANSFER_PAIR');
  else r := r || '{"V-08":"ok"}'; end if;
  -- V-09 review queue: rows marked for review (uncategorized / needs_review) hold the plan
  if exists (select 1 from bnx.posting_plan_item i where i.plan_id = p_plan
              and (coalesce((i.payload->>'needs_review')::boolean, false) or (not i.payload ? 'lines' and not i.payload ? 'counter_ledger_account_id'))) then
    r := r || '{"V-09":"HOLD:REVIEW_QUEUE"}'; holds := array_append(holds, 'REVIEW_QUEUE');
  else r := r || '{"V-09":"ok"}'; end if;
  -- V-10 module flag of the plan's scope (9007)
  begin
    perform bnx.pol_require_module_for_ac(acid);
    r := r || '{"V-10":"ok"}';
  exception when sqlstate 'P0403' then
    r := r || jsonb_build_object('V-10', 'HOLD:SCOPE (' || sqlerrm || ')'); holds := array_append(holds, 'SCOPE');
  end;
  -- V-11 statement continuity (9043): the opening balance meets the closing balance of the nearest earlier live statement of
  --      the same account-currency. A break holds the plan unless a member recorded an explanation; a calendar gap with
  --      matching balances is a finding only (no activity is the usual cause)
  if st is not null then                                                                                                 -- 9043
    cont := bnx.statement_continuity(p_plan);                                                                            -- 9043
    if cont->>'status' = 'break' then                                                                                    -- 9043
      r := r || jsonb_build_object('V-11', 'HOLD:BALANCE_BREAK (previous closing ' || (cont->>'previous_closing') || ' on '   -- 9043
                                   || (cont->>'previous_period_to') || ', opening ' || (cont->>'opening') || ')');        -- 9043
      holds := array_append(holds, 'BALANCE_BREAK');                                                                     -- 9043
    elsif cont->>'status' = 'gap' then                                                                                   -- 9043
      r := r || jsonb_build_object('V-11', 'FINDING:GAP (' || (cont->>'gap_from') || '..' || (cont->>'gap_to') || ')');   -- 9043
    else r := r || jsonb_build_object('V-11', cont->>'status'); end if;                                                  -- 9043
  else r := r || '{"V-11":"n/a"}'; end if;                                                                               -- 9043
  -- V-12 opening anchor (9043): no item may fall before the opening anchor of a household account it touches; the posting
  --      worker would refuse it after approval (POSTINGS_BEFORE_ANCHOR). For history the anchor moves to the earliest statement
  if exists (select 1 from bnx.posting_plan_item i                                                                       -- 9043
               cross join lateral jsonb_array_elements(bnx.plan_item_lines(p_plan, i.payload)) l                          -- 9043
               join bnx.account_currency x on x.ledger_account_id = (l->>'ledger_account_id')::uuid                        -- 9043
              where i.plan_id = p_plan                                                                                    -- 9043
                and (i.payload->>'transaction_date')::date < (bnx.anchor_at(x.id, 9223372036854775807)).anchor_date) then -- 9043
    r := r || '{"V-12":"HOLD:BEFORE_OPENING"}'; holds := array_append(holds, 'BEFORE_OPENING');                          -- 9043
  else r := r || '{"V-12":"ok"}'; end if;                                                                                -- 9043
  update bnx.posting_plan set validation_result = r, hold_reasons = holds, validated_at_version = last_validated_version where id = p_plan;
  return jsonb_build_object('validation_result', r, 'hold_reasons', to_jsonb(holds), 'validated_at_version', pl.last_validated_version);
end $$;

